53. /** Maximum number of log lines to keep in the debug panel. */
54. const MAX_DEBUG_LOG_LINES = 200;
55. 
56. /** Cached DOM element references for the debug panel (avoid re-querying every call). */
57. let _debugLogEl: HTMLElement | null | undefined;
58. let _debugStateEl: HTMLElement | null | undefined;
59. 
60. function getDebugLogEl(): HTMLElement | null {
61.   if (_debugLogEl === undefined) _debugLogEl = document.getElementById("debug-log");
62.   return _debugLogEl;
63. }
