70. /** Append a message to the HTML debug log panel. */
71. export function debugPanelLog(msg: string, isDebugMsg = false, cssClass?: string): void {
72.   const el = getDebugLogEl();
73.   if (!el) return;
74.   // Remove previous spacer if present
75.   const oldSpacer = el.querySelector(".log-spacer");
76.   if (oldSpacer) oldSpacer.remove();
77.   // Add the log line
78.   const line = document.createElement("div");
79.   line.textContent = msg;
80.   if (cssClass) line.className = cssClass;
81.   else if (isDebugMsg) line.className = "debug-msg";
82.   el.appendChild(line);
83.   // Trim oldest lines if over limit
84.   const lines = el.querySelectorAll("div:not(.log-spacer)");
85.   if (lines.length > MAX_DEBUG_LOG_LINES) {
86.     const toRemove = lines.length - MAX_DEBUG_LOG_LINES;
87.     for (let i = 0; i < toRemove; i++) lines[i].remove();
88.   }
89.   // Add trailing spacer for readability
90.   const spacer = document.createElement("div");
91.   spacer.className = "log-spacer";
92.   el.appendChild(spacer);
93.   // Auto-scroll to bottom
94.   el.scrollTop = el.scrollHeight;
95. }
