113. type DebugCommandHandler = (command: string, args: string) => void;
114. let _debugCommandHandler: DebugCommandHandler | null = null;
115. 
116. /** Register a command handler for the debug text input. Called by the active scene. */
117. export function setDebugCommandHandler(handler: DebugCommandHandler | null): void {
118.   _debugCommandHandler = handler;
119. }
120. 
121. /** Initialize the debug command input listener (called once on startup). */
122. export function initDebugCommandInput(): void {
123.   const input = document.getElementById("debug-cmd") as HTMLInputElement | null;
124.   if (!input) return;
125.   input.addEventListener("keydown", (e) => {
126.     e.stopPropagation(); // prevent Phaser from capturing keys while typing
127.     if (e.key === "Enter") {
128.       const raw = input.value.trim();
129.       input.value = "";
130.       if (!raw.startsWith("/")) {
131.         debugPanelLog(`Unknown command: ${raw}. For a list of commands try /help. Commands start with /`, true);
132.         return;
133.       }
134.       if (!_debug) {
135.         debugPanelLog("Debug mode is off!", true);
136.         return;
137.       }
138.       const parts = raw.slice(1).split(/\s+/);
139.       const cmd = parts[0].toLowerCase();
140.       const args = parts.slice(1).join(" ");
141.       if (_debugCommandHandler) {
142.         _debugCommandHandler(cmd, args);
143.       } else {
144.         debugPanelLog(`No active command handler.`, true);
145.       }
146.     }
147.   });
148.   // Prevent Phaser from stealing focus events  
149.   input.addEventListener("keyup", (e) => e.stopPropagation());
150.   input.addEventListener("keypress", (e) => e.stopPropagation());
151. }
