4. 
5. const DEFAULT_FADE_DURATION = 300;
6. const WATCHDOG_GRACE_MS = 250;
7. 
8. export interface SceneFadeOptions {
9.   duration?: number;
10.   red?: number;
11.   green?: number;
12.   blue?: number;
13.   label?: string;
14. }
