23. export class SceneTransitionManager {
24.   private pending = false;
25.   private scheduledTimer: Phaser.Time.TimerEvent | null = null;
26.   private cameraWait: CameraWait | null = null;
27.   private cameraWaitId = 0;
28. 
29.   constructor(private readonly scene: Phaser.Scene) {}
30. 
31.   get isPending(): boolean {
32.     return this.pending;
33.   }
34. 
35.   prepare(
36.     fadeInDuration = 0,
37.     red = 0,
38.     green = 0,
39.     blue = 0,
40.   ): void {
41.     this.cancelScheduledTimer();
42.     this.cancelCameraWait();
43.     this.pending = false;
44.     this.restoreCamera();
45. 
46.     const duration = getMotionDuration(fadeInDuration);
47.     if (duration <= 0) return;
48. 
49.     this.waitForCameraEffect(
50.       Phaser.Cameras.Scene2D.Events.FADE_IN_COMPLETE,
51.       duration,
52.       "scene fade-in",
53.       () => this.restoreCamera(),
54.     );
55.     this.scene.cameras.main.fadeIn(
56.       duration,
57.       red,
58.       green,
59.       blue,
60.     );
61.   }
62. 
63.   startWithFade(
64.     startScene: () => void,
65.     options: SceneFadeOptions = {},
66.   ): boolean {
67.     const label = options.label ?? "scene handoff";
68.     if (!this.beginTransition(label)) return false;
69. 
70.     const duration = getMotionDuration(
71.       options.duration ?? DEFAULT_FADE_DURATION,
72.     );
73.     const red = options.red ?? 0;
74.     const green = options.green ?? 0;
75.     const blue = options.blue ?? 0;
76. 
77.     if (duration <= 0) {
78.       this.completeSceneHandoff(startScene);
79.       return true;
80.     }
81.     this.waitForCameraEffect(
82.       Phaser.Cameras.Scene2D.Events.FADE_OUT_COMPLETE,
83.       duration,
84.       label,
85.       () => this.completeSceneHandoff(startScene),
86.     );
87.     this.scene.cameras.main.fadeOut(duration, red, green, blue);
88.     return true;
89.   }
90. 
91.   startImmediately(startScene: () => void, label = "scene handoff"): boolean {
92.     if (!this.beginTransition(label)) return false;
93.     this.completeSceneHandoff(startScene);
94.     return true;
95.   }
96. 
97.   startAfter(
98.     delay: number,
99.     startScene: () => void,
100.     label = "delayed scene handoff",
101.   ): boolean {
102.     if (!this.beginTransition(label)) return false;
103. 
104.     this.scheduledTimer = this.scene.time.delayedCall(delay, () => {
105.       this.scheduledTimer = null;
106.       if (!this.pending) return;
107.       this.completeSceneHandoff(startScene);
108.     });
109.     return true;
110.   }
111. 
112.   fadeOutAndIn(
113.     atBlack: () => void,
114.     options: SceneFadeOptions = {},
115.   ): boolean {
116.     const label = options.label ?? "same-scene fade";
117.     if (!this.beginTransition(label)) return false;
118. 
119.     const duration = getMotionDuration(
120.       options.duration ?? DEFAULT_FADE_DURATION,
121.     );
122.     const red = options.red ?? 0;
123.     const green = options.green ?? 0;
124.     const blue = options.blue ?? 0;
125. 
126.     if (duration <= 0) {
127.       this.restoreCamera();
128.       atBlack();
129.       this.pending = false;
130.       return true;
131.     }
132.     this.waitForCameraEffect(
133.       Phaser.Cameras.Scene2D.Events.FADE_OUT_COMPLETE,
134.       duration,
135.       `${label} fade-out`,
136.       () => {
137.         this.restoreCamera();
138.         atBlack();
139.         this.waitForCameraEffect(
140.           Phaser.Cameras.Scene2D.Events.FADE_IN_COMPLETE,
141.           duration,
142.           `${label} fade-in`,
143.           () => {
144.             this.restoreCamera();
145.             this.pending = false;
146.           },
147.         );
148.         this.scene.cameras.main.fadeIn(duration, red, green, blue);
149.       },
150.     );
151.     this.scene.cameras.main.fadeOut(duration, red, green, blue);
152.     return true;
153.   }
154. 
155.   private beginTransition(label: string): boolean {
156.     if (this.pending) {
157.       debugLog(
158.         `[SCENE] Ignored duplicate transition in ${this.scene.sys.settings.key}: ${label}`,
159.       );
160.       return false;
161.     }
162. 
163.     this.cancelScheduledTimer();
164.     this.cancelCameraWait();
165.     this.pending = true;
166.     this.restoreCamera();
167.     return true;
168.   }
169. 
170.   private completeSceneHandoff(startScene: () => void): void {
171.     this.cancelScheduledTimer();
172.     this.cancelCameraWait();
173.     this.restoreCamera();
174.     startScene();
175.   }
176. 
177.   private waitForCameraEffect(
178.     event: string,
179.     duration: number,
180.     label: string,
181.     onComplete: () => void,
182.   ): void {
183.     this.cancelCameraWait();
184.     const id = this.cameraWaitId;
185.     let settled = false;
186.     let handler: () => void;
187. 
188.     const finish = (recovered: boolean): void => {
189.       if (settled || id !== this.cameraWaitId) return;
190.       settled = true;
191.       this.clearCameraWait(id);
192.       if (recovered) {
193.         debugLog(
194.           `[SCENE] Recovered stalled camera effect in ${this.scene.sys.settings.key}: ${label}`,
195.         );
196.       }
197.       onComplete();
198.     };
199. 
200.     handler = () => finish(false);
201.     this.scene.cameras.main.once(event, handler);
202.     const watchdog = this.scene.time.delayedCall(
203.       Math.max(0, duration) + WATCHDOG_GRACE_MS,
204.       () => finish(true),
205.     );
206.     this.cameraWait = { event, handler, watchdog, id };
207.   }
208. 
209.   private clearCameraWait(id: number): void {
210.     const wait = this.cameraWait;
211.     if (!wait || wait.id !== id) return;
212. 
213.     this.scene.cameras.main.off(wait.event, wait.handler);
214.     wait.watchdog.remove(false);
215.     this.cameraWait = null;
216.   }
217. 
218.   private cancelCameraWait(): void {
219.     this.cameraWaitId += 1;
220.     const wait = this.cameraWait;
221.     if (!wait) return;
222. 
223.     this.scene.cameras.main.off(wait.event, wait.handler);
224.     wait.watchdog.remove(false);
225.     this.cameraWait = null;
226.   }
227. 
228.   private cancelScheduledTimer(): void {
229.     this.scheduledTimer?.remove(false);
230.     this.scheduledTimer = null;
231.   }
232. 
233.   private restoreCamera(): void {
234.     this.scene.cameras.main.resetFX();
235.     this.scene.cameras.main.setVisible(true);
236.     this.scene.cameras.main.setAlpha(1);
237.   }
238. }
