const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');
const files = execFileSync('git', ['ls-files', '*.md'], {encoding:'utf8'}).trim().split('\n').filter(Boolean);
const errors = [];
for (const file of files) {
  const text = fs.readFileSync(file, 'utf8');
  const links = [...text.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)].map(m => m[1]);
  for (const raw of links) {
    if (/^(https?:|mailto:|#)/.test(raw)) continue;
    const [target, anchor] = raw.split('#');
    const resolved = path.resolve(path.dirname(file), decodeURI(target));
    if (!fs.existsSync(resolved)) {
      errors.push(`${file}: missing ${raw}`);
      continue;
    }
    if (anchor && fs.statSync(resolved).isFile() && resolved.endsWith('.md')) {
      const headings = fs.readFileSync(resolved, 'utf8').split(/\r?\n/)
        .filter(line => /^#{1,6}\s/.test(line))
        .map(line => line.replace(/^#{1,6}\s+/, '').trim().toLowerCase()
