const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');
const tracked = execFileSync('git', ['ls-files', '*.md'], {encoding:'utf8'}).trim().split('\n').filter(Boolean);
const docs = fs.readdirSync('docs').filter(f => f.endsWith('.md')).map(f => `docs/${f}`);
const files = [...new Set([...tracked, 'AGENTS.md', 'README.md', ...docs])].filter(fs.existsSync);
const errors = [];
for (const file of files) {
  const text = fs.readFileSync(file, 'utf8');
  for (const match of text.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)) {
    const raw = match[1];
    if (/^(https?:|mailto:|#)/.test(raw)) continue;
    const [target, anchor] = raw.split('#');
    const resolved = path.resolve(path.dirname(file), decodeURI(target));
    if (!fs.existsSync(resolved)) { errors.push(`${file}: missing ${raw}`); continue; }
    if (!anchor || !resolved.endsWith('.md')) continue;
    const headings = fs.readFileSync(resolved, 'utf8').split(/\r?\n/)
      .filter(line => /^#{1,6}\s/.test(line))
      .map(line => line.replace(/^#{1,6}\s+/, '').trim().toLowerCase()
        .replace(/[`*_~]/g, '').replace(/[^a-z0-9\s-]/g, '')
        .replace(/\s+/g, '-').replace(/-+/g, '-'));
    if (!headings.includes(anchor.toLowerCase())) errors.push(`${file}: missing anchor ${raw}`);
  }
}
if (errors.length) { console.error(errors.join('\n')); process.exit(1); }
console.log(`Checked ${files.length} Markdown files: relative links and anchors resolve.`);
